/** The `data` of the 200 success envelope. */
declare type DataOf<O extends OperationId> = Extract<Answer_2<O>, {
    ok: true;
}> extends {
    data: infer D;
} ? D : never;

/** An exact decimal: the value times 10^18, in a bigint. Prices, sizes, amounts and rates all use it. */
export declare type Dec = bigint & {
    readonly [decBrand]: true;
};

export declare const dec: DecApi;

declare interface DecApi {
    readonly zero: Dec;
    readonly one: Dec;
    /** Accepts DEC_PATTERN only; throws AppError('invalid_decimal'). */
    parse(text: string): Dec;
    tryParse(text: string): Dec | null;
    /** Canonical: no exponent, no '+', no trailing fractional zeros, no trailing '.', "0" for zero, never "-0". */
    format(value: Dec): string;
    fromBigint(whole: bigint): Dec;
    /** units × 10^-decimals; exact when decimals <= 18, otherwise rounded by mode. */
    fromUnits(units: bigint, decimals: number, mode: RoundingMode): Dec;
    /** value × 10^decimals, rounded by mode (token base units at payout use 'down'). */
    toUnits(value: Dec, decimals: number, mode: RoundingMode): bigint;
    add(a: Dec, b: Dec): Dec;
    sub(a: Dec, b: Dec): Dec;
    neg(a: Dec): Dec;
    abs(a: Dec): Dec;
    /** The exact 36-place product, rounded once to 18 places. */
    mul(a: Dec, b: Dec, mode: RoundingMode): Dec;
    /** Throws AppError('division_by_zero') when b is zero. */
    div(a: Dec, b: Dec, mode: RoundingMode): Dec;
    /** A multiple of step (step > 0), chosen by mode. */
    quantize(value: Dec, step: Dec, mode: RoundingMode): Dec;
    cmp(a: Dec, b: Dec): -1 | 0 | 1;
    eq(a: Dec, b: Dec): boolean;
    lt(a: Dec, b: Dec): boolean;
    lte(a: Dec, b: Dec): boolean;
    gt(a: Dec, b: Dec): boolean;
    gte(a: Dec, b: Dec): boolean;
    sign(a: Dec): -1 | 0 | 1;
    min(a: Dec, b: Dec): Dec;
    max(a: Dec, b: Dec): Dec;
    sum(values: readonly Dec[]): Dec;
    /** |value| < 10^20: fits numeric(38,18). Every database writer asserts it. */
    fits(value: Dec): boolean;
}

declare const decBrand: unique symbol;

declare type Detail = string | number | boolean | null;

