export declare type ReplayClientFrame = components['schemas']['ReplayClientFrame'];

export declare interface ReplayHandle {
    readonly done: Promise<string>;
    send(frame: Exclude<ReplayClientFrame, {
        t: 'open';
    }>): void;
    close(): void;
}

export declare type ReplayServerFrame = components['schemas']['ReplayServerFrame'];

/** down: toward zero; up: away from zero; floor: toward −∞; ceil: toward +∞; half_even: to nearest, ties to even. */
declare type RoundingMode = 'down' | 'up' | 'floor' | 'ceil' | 'half_even';

declare type Route = DataOf<'getRoute'>;

export declare type RouteAnswer = Extract<Answer<'placeOrder' | 'getRoute' | 'quoteRoute'>, {
    readonly ok: false;
}> | {
    readonly ok: true;
    readonly data: Route;
    readonly requestId: string;
};

export declare type RouteExecuteInput = RoutePlaceInput & {
    readonly followUp?: boolean;
};

export declare interface RouteInput {
    readonly group: string;
    readonly side: 'buy' | 'sell';
    readonly type: 'market' | 'limit';
    readonly tif?: 'ioc' | 'gtc' | 'post_only';
    readonly price?: Dec | string;
    readonly size?: Dec | string;
    readonly notional?: Dec | string;
    readonly reduceOnly?: boolean;
    readonly maxSlippageBps?: number;
    readonly tp?: OrderTriggerInput;
    readonly sl?: OrderTriggerInput;
    readonly fundingHorizonHours?: number;
    readonly split?: boolean;
    readonly maxLegs?: number;
    readonly crossClass?: boolean;
    readonly allowPartial?: boolean;
    readonly accountIds?: readonly string[];
    readonly mode?: 'gateway' | 'direct';
}

declare type RouteLeg = Route['legs'][number];

export declare type RoutePlaceInput = RouteInput & {
    readonly quoteId?: string;
    readonly clientRouteId?: string;
};

export declare interface SocketCallbacks {
    readonly open: () => void;
    readonly message: (data: string) => void;
    readonly close: (code: number) => void;
    readonly error: () => void;
}

export declare type SocketFactory = (address: string, headers: Readonly<Record<string, string>>, callbacks: SocketCallbacks) => WireSocket;

export declare interface StreamEvent {
    readonly seq: string;
    readonly kind: string;
    readonly data: unknown;
}

export declare interface StreamHandle {
    readonly lastSeq: () => string | null;
    readonly done: Promise<void>;
    close(): Promise<void>;
}

export declare interface StreamOptions {
    readonly channels: readonly string[];
    readonly since?: string;
    readonly onEvent: (event: StreamEvent) => void | Promise<void>;
    readonly onReset: (latestSeq: string) => void | Promise<void>;
    readonly onMarket?: (channel: string, data: unknown) => void;
}

declare class Transport {
    #private;
    readonly origin: string;
    readonly now: () => number;
    readonly signed: boolean;
    constructor(options: TransportOptions);
    headers(method: string, target: string, body: Uint8Array): Record<string, string>;
    dispatch(request: Request, id: OperationId): Promise<Response>;
}

declare interface TransportOptions {
    readonly baseUrl: string;
    readonly key?: Key;
    readonly fetch?: typeof globalThis.fetch;
    readonly now?: () => number;
    readonly timeoutMs?: number;
    readonly retry?: {
        readonly attempts: number;
        readonly baseDelayMs: number;
    };
}

export declare interface WalletProof {
    readonly signature: string;
    readonly scheme: 'eip191' | 'solana' | 'adr36';
}

export declare interface WireSocket {
    send(frame: string): void;
    close(): void;
}

export { }
